files.db.js:
// The data layer.
export function findUser(id) {
  return { id, name: 'gev' };
}

files.api.js:
import { findUser } from './db.js';

// The request layer.
export function handle(req) {
  return findUser(req.id);
}

files.app.js:
import { handle } from './api.js';

// The entry point.
export function run(id) {
  return handle({ id });
}

files.test.mjs:
import { findUser } from './db.js';
import { handle } from './api.js';
import { run } from './app.js';

let bad = 0;
const a = findUser(3, 'trace-a');
if (!a || a.trace !== 'trace-a' || a.id !== 3) { console.error('db.js: findUser(3, "trace-a") gave ' + JSON.stringify(a)); bad = 1; }
const b = handle({ id: 4 }, 'trace-b');
if (!b || b.trace !== 'trace-b' || b.id !== 4) { console.error('api.js: handle({ id: 4 }, "trace-b") gave ' + JSON.stringify(b)); bad = 1; }
const c = run(5, 'trace-c');
if (!c || c.trace !== 'trace-c' || c.id !== 5) { console.error('app.js: run(5, "trace-c") gave ' + JSON.stringify(c)); bad = 1; }
process.exit(bad);
